// Server-rendered page: no JavaScript, no external assets, one small SVG map -> works on weak connections.
function rows(name) {
  try { return $(name).all().map(function (i) { return i.json; }).filter(function (j) { return j && j.id !== undefined; }); } catch (e) { return []; }
}
function esc(s) { return String(s === null || s === undefined ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;'); }
function num(v) { var n = Number(v); return (v === null || v === undefined || v === '' || !isFinite(n)) ? null : n; }
function fmt(v, d) { var n = num(v); return n === null ? 'n/a' : n.toFixed(d === undefined ? 0 : d); }
var now = Date.now();
function ageH(iso) { var t = Date.parse(iso); return isFinite(t) ? (now - t) / 3600000 : null; }
function local(iso) { var t = Date.parse(iso); if (!isFinite(t)) return 'n/a'; return new Date(t).toLocaleString('en-GB', { timeZone: 'Asia/Karachi', dateStyle: 'medium', timeStyle: 'short' }) + ' PKT'; }

var hot = rows('Read Hotspots');
var obs = rows('Read Observations');
var fires = rows('Read Fires');
var fc = rows('Read Forecast');
var logs = rows('Read Pull Log');

// --- Source health (never present old data as current) ---
var latest = {};
logs.forEach(function (l) { if (!latest[l.source]) latest[l.source] = l; });
var specs = [
  ['open-meteo-cams', 'CAMS air quality (via Open-Meteo)', 3, true],
  ['open-meteo-weather', 'Weather and wind (Open-Meteo)', 3, true],
  ['nasa-firms', 'NASA FIRMS active fires', 3, true],
  ['openaq', 'OpenAQ ground sensors', 3, false],
  ['osm-facilities', 'OpenStreetMap industrial sites', 240, false],
  ['detection', 'Hotspot detection', 3, true],
  ['forecast', '12-hour forecast model', 8, true]
];
var srcHtml = '';
var problems = [];
for (var s = 0; s < specs.length; s++) {
  var sp = specs[s];
  var l = latest[sp[0]];
  var state = 'NO DATA YET';
  var cls = 'bad';
  var when = 'never';
  var msg = '';
  if (l) {
    var a = ageH(l.run_at);
    when = local(l.run_at);
    msg = l.message;
    if (l.status === 'ok' && a !== null && a <= sp[2]) { state = 'OK'; cls = 'ok'; }
    else if (l.status === 'ok') { state = 'STALE (' + Math.round(a) + ' h old)'; cls = 'bad'; }
    else if (l.status === 'partial') { state = 'PARTIAL'; cls = 'warn'; }
    else { state = String(l.status).toUpperCase(); cls = 'bad'; }
  }
  if (cls !== 'ok' && sp[3]) problems.push(sp[1] + ': ' + state);
  srcHtml += '<tr><td>' + esc(sp[1]) + '</td><td class="' + cls + '">' + esc(state) + '</td><td>' + esc(when) + '</td><td>' + esc(l ? l.records : '') + '</td><td class="small">' + esc(msg) + '</td></tr>';
}

// --- Hotspots of the latest successful detection run only ---
var det = latest['detection'];
var detOk = det && det.status === 'ok' && ageH(det.run_at) !== null && ageH(det.run_at) <= 3;
var shown = detOk ? hot.filter(function (h) { return h.run_id === det.run_id; }) : [];
shown.sort(function (x, y) { return Number(y.priority_score) - Number(x.priority_score); });
var lastUpdated = det ? det.run_at : null;

// --- Latest grid observation per cell (only if fresh) ---
var cells = [];
var seen = {};
obs.forEach(function (o) {
  if (seen[o.cell_id]) return;
  seen[o.cell_id] = true;
  var a2 = ageH(o.observed_at);
  if (a2 !== null && a2 <= 4) cells.push(o);
});

// --- SVG map ---
var W = 560, Hh = 560, lonMin = 73.9, lonMax = 74.7, latMin = 31.15, latMax = 31.85;
function X(lon) { return Math.round((lon - lonMin) / (lonMax - lonMin) * W * 10) / 10; }
function Y(lat) { return Math.round((latMax - lat) / (latMax - latMin) * Hh * 10) / 10; }
function pmColor(p) { return p < 35 ? '#8bc34a' : p < 55 ? '#ffeb3b' : p < 100 ? '#ff9800' : p < 150 ? '#f44336' : '#8e24aa'; }
function sevColor(sv) { return sv === 'severe' ? '#4a148c' : sv === 'high' ? '#b71c1c' : '#e65100'; }
var cw = 0.15 / (lonMax - lonMin) * W, ch = 0.125 / (latMax - latMin) * Hh;
var svg = '<svg viewBox="0 0 ' + W + ' ' + Hh + '" width="100%" role="img" aria-label="Hotspot map of Lahore region" style="max-width:640px;background:#eef3f7;border:1px solid #bbb">';
cells.forEach(function (c) {
  var p = Number(c.pm25);
  svg += '<rect x="' + (X(Number(c.lon)) - cw / 2) + '" y="' + (Y(Number(c.lat)) - ch / 2) + '" width="' + cw + '" height="' + ch + '" fill="' + pmColor(p) + '" fill-opacity="0.55" stroke="#fff"><title>' + esc(c.cell_id) + ' PM2.5 ' + fmt(p) + ' ug/m3, wind from ' + fmt(c.wind_dir) + ' deg</title></rect>';
  svg += '<text x="' + X(Number(c.lon)) + '" y="' + (Y(Number(c.lat)) + 4) + '" font-size="11" text-anchor="middle" fill="#333">' + fmt(p) + '</text>';
});
fires.forEach(function (f) {
  var fa = ageH(f.acq_time);
  var la = num(f.lat), lo = num(f.lon);
  if (la === null || lo === null || fa === null || fa > 36 || la < latMin || la > latMax || lo < lonMin || lo > lonMax) return;
  svg += '<circle cx="' + X(lo) + '" cy="' + Y(la) + '" r="3.5" fill="#ff3d00" stroke="#000" stroke-width="0.8"><title>Fire detection ' + esc(f.acq_time) + ' FRP ' + fmt(f.frp, 1) + '</title></circle>';
});
svg += '<circle cx="' + X(74.35) + '" cy="' + Y(31.52) + '" r="3" fill="#1565c0"/><text x="' + (X(74.35) + 6) + '" y="' + (Y(31.52) - 4) + '" font-size="11" fill="#1565c0">Lahore</text>';
shown.slice(0, 25).forEach(function (h, idx) {
  svg += '<circle cx="' + X(Number(h.lon)) + '" cy="' + Y(Number(h.lat)) + '" r="13" fill="none" stroke="' + sevColor(h.severity) + '" stroke-width="3"><title>#' + (idx + 1) + ' ' + esc(h.attribution) + '</title></circle>';
  svg += '<text x="' + X(Number(h.lon)) + '" y="' + (Y(Number(h.lat)) + 4) + '" font-size="12" font-weight="bold" text-anchor="middle" fill="' + sevColor(h.severity) + '">' + (idx + 1) + '</text>';
});
svg += '</svg>';

// --- Hotspot table ---
var tbl = '';
shown.slice(0, 25).forEach(function (h, idx) {
  var link = 'https://www.openstreetmap.org/?mlat=' + h.lat + '&mlon=' + h.lon + '#map=13/' + h.lat + '/' + h.lon;
  tbl += '<tr><td>' + (idx + 1) + '</td><td class="sev-' + esc(h.severity) + '">' + esc(String(h.severity).toUpperCase()) + '</td><td>' + fmt(h.pm25) + '</td><td>' + esc(h.attribution) + '<br><span class="small">confidence: ' + esc(h.attribution_confidence) + '</span></td>';
  tbl += '<td class="small">fires upwind ' + esc(h.fires_upwind) + ', near ' + esc(h.fires_nearby) + '; industrial sites ' + esc(h.facilities_nearby) + '; ground sensor: ' + esc(h.ground_agreement) + (num(h.ground_pm25) !== null ? ' (' + fmt(h.ground_pm25) + ')' : '') + '<details><summary>evidence</summary>' + esc(h.evidence) + '</details></td>';
  tbl += '<td><a href="' + esc(link) + '">map</a></td></tr>';
});
if (!tbl) tbl = '<tr><td colspan="6">' + (detOk ? 'No hotspots flagged in the latest run.' : 'No current hotspot list: the latest detection run is missing, failed or stale. Older results are intentionally hidden.') + '</td></tr>';

// --- Forecast card ---
var fcHtml = '<p>No forecast available yet.</p>';
var f0 = fc[0];
if (f0) {
  var fa2 = ageH(f0.issued_at);
  var fStale = fa2 === null || fa2 > 8;
  fcHtml = '<p>Issued ' + esc(local(f0.issued_at)) + ' for ' + esc(local(f0.target_time)) + (fStale ? ' <b class="bad">STALE - do not rely on it</b>' : '') + '</p>';
  fcHtml += '<table><tr><th></th><th>PM2.5 (ug/m3)</th><th>MAE</th><th>RMSE</th></tr>';
  fcHtml += '<tr><td><b>Model (ridge)</b></td><td><b>' + fmt(f0.pm25_model) + '</b></td><td>' + fmt(f0.mae_model, 1) + '</td><td>' + fmt(f0.rmse_model, 1) + '</td></tr>';
  fcHtml += '<tr><td>Baseline: nothing changes</td><td>' + fmt(f0.pm25_persistence) + '</td><td>' + fmt(f0.mae_persistence, 1) + '</td><td>' + fmt(f0.rmse_persistence, 1) + '</td></tr>';
  fcHtml += '<tr><td>Baseline: seasonal average</td><td>' + fmt(f0.pm25_seasonal) + '</td><td>' + fmt(f0.mae_seasonal, 1) + '</td><td>' + fmt(f0.rmse_seasonal, 1) + '</td></tr>';
  fcHtml += '<tr><td>CAMS own forecast (reference)</td><td>' + fmt(f0.pm25_cams) + '</td><td>-</td><td>-</td></tr></table>';
  fcHtml += '<p class="small">Now: ' + fmt(f0.pm25_now) + ' ug/m3. Hold-out test on ' + esc(f0.test_rows) + ' unseen hours (trained on ' + esc(f0.train_rows) + '). ' + (f0.beats_baselines === true || f0.beats_baselines === 'true' ? 'The model currently beats both baselines.' : 'The model does NOT currently beat both baselines; the numbers above are reported honestly.') + '</p>';
}

var banner = problems.length ? '<div class="banner">DATA PROBLEM - results may be incomplete or out of date. ' + esc(problems.join(' | ')) + '</div>' : '';
var html = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="300"><title>Lahore smoke hotspots</title>';
html += '<style>body{font-family:Arial,sans-serif;margin:12px;color:#222;max-width:980px}h1{font-size:20px;margin:0 0 4px}h2{font-size:16px;margin:18px 0 6px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border:1px solid #ccc;padding:4px 6px;text-align:left;vertical-align:top}th{background:#f0f0f0}.small{font-size:11px;color:#555}.ok{color:#1b5e20;font-weight:bold}.warn{color:#e65100;font-weight:bold}.bad{color:#b71c1c;font-weight:bold}.banner{background:#ffebee;border:2px solid #b71c1c;color:#b71c1c;padding:8px;margin:8px 0;font-weight:bold}.sev-SEVERE{color:#4a148c;font-weight:bold}.sev-HIGH{color:#b71c1c;font-weight:bold}.sev-ELEVATED{color:#e65100;font-weight:bold}.legend span{display:inline-block;padding:1px 6px;margin-right:4px;font-size:11px;border:1px solid #999}</style></head><body>';
html += '<h1>Lahore region: where to look first</h1>';
html += '<div>Last successful detection: <b>' + esc(lastUpdated ? local(lastUpdated) : 'never') + '</b>' + (lastUpdated ? ' (' + Math.round(ageH(lastUpdated) * 10) / 10 + ' h ago)' : '') + ' - page refreshes every 5 minutes</div>';
html += banner;
html += '<h2>Ranked hotspots</h2><table><tr><th>#</th><th>Level</th><th>PM2.5</th><th>Likely source</th><th>Evidence</th><th>Location</th></tr>' + tbl + '</table>';
html += '<h2>Map</h2>' + svg;
html += '<div class="legend small">Grid PM2.5: <span style="background:#8bc34a">&lt;35</span><span style="background:#ffeb3b">35-55</span><span style="background:#ff9800">55-100</span><span style="background:#f44336">100-150</span><span style="background:#8e24aa;color:#fff">150+</span> Orange dots = fires (36 h). Numbered rings = ranked hotspots.</div>';
html += '<h2>12-hour forecast (Lahore centre)</h2>' + fcHtml;
html += '<h2>Data source health</h2><table><tr><th>Source</th><th>Status</th><th>Last pull</th><th>Records</th><th>Message</th></tr>' + srcHtml + '</table>';
html += '<h2>Read this first</h2><p class="small">Research prototype built on public data only; not an official government system. Satellites and models are coarse and clouds or haze can hide fires, so results point to an area and cannot prove that a specific business broke the law. Source labels are rule-based estimates marked likely or possible. Every flag must be confirmed by field inspection before any action.</p>';
html += '</body></html>';
return [{ json: { html: html } }];
